            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 5 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            guides.append(comp)

    # The colored object touching a guide is copied repeatedly along it.
    for guide in guides:
        rows = [p[0] for p in guide]
        cols = [p[1] for p in guide]
        vertical = len(set(cols)) == 1
        horizontal = len(set(rows)) == 1
        if not (vertical or horizontal):
            continue
        axis = 0 if vertical else 1
        lo, hi = min(rows if axis == 0 else cols), max(rows if axis == 0 else cols)
        cells5 = set(guide)

        # Flood-fill all nonzero, non-5 objects and choose the one touching this guide.
        colored_seen = set()
        sources = []
        for y in range(h):
            for x in range(w):
                if grid[y][x] in (0, 5) or (y, x) in colored_seen:
                    continue
                q = [(y, x)]
                colored_seen.add((y, x))
                obj = []
                while q:
                    a, b = q.pop()
                    obj.append((a, b))
                    for aa, bb in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                        if 0 <= aa < h and 0 <= bb < w and grid[aa][bb] not in (0,5) and (aa,bb) not in colored_seen:
                            colored_seen.add((aa,bb)); q.append((aa,bb))
                if any(abs(a-y0)+abs(b-x0) == 1 for a,b in obj for y0,x0 in guide):
                    sources.append(obj)
        if not sources:
            continue

        # Source should be the touching object nearest the guide midpoint.
        def distance(obj):
            vals = [p[axis] for p in obj]
            mid = (min(vals)+max(vals))/2
            return abs(mid-(lo+hi)/2)
        source = min(sources, key=distance)
        vals = [p[axis] for p in source]
        slo, shi = min(vals), max(vals)
        step = shi - slo + 1
        # Extend away from the source end, keeping its internal pattern intact.
        direction = 1 if (slo+shi)/2 <= (lo+hi)/2 else -1
        if direction > 0:
